"""Independent slow reference for the exact envelope / peaks / guard / warmup."""
from math import gcd
import heapq


def period(T, S, Q):
    m = Q * S
    return m // gcd(m, T)


def build(profile, fabric):
    K = profile['groups']
    jit = profile['jitter_ps']
    cal = None
    return K, jit


def hop(profile, upper):
    K = profile['groups']
    jit = profile['jitter_ps']
    H = [[(upper[a][b] + upper[b][a]) * 500 + (jit[a] + jit[b]) * 1000
          for b in range(K)] for a in range(K)]
    return H


class Ref:
    def __init__(self, profile, fabric):
        self.K = profile['groups']
        self.jit = profile['jitter_ps']
        cal = None
        self.fab = fabric
        self.n = n = fabric['n']
        self.T = T = fabric['interval_ns']
        self.S = S = fabric['slice_ns']
        self.O = O = fabric['offset_ns']
        self.slices = fabric['slices']
        self.Q = len(self.slices)
        self.P = P = period(T, S, self.Q)
        self.guards = fabric['guards_ns']
        self.reconf = fabric['reconfig_ns']
        # drift
        v = [[fabric['drift_ppb'][i] for _ in range(P)] for i in range(n)]
        for node, st, en, extra in fabric['heat']:
            for p in range(st, en):
                v[node][p] += extra
        self.v = v
        # anchors
        self.anch = [[False] * P for _ in range(n)]
        for node, st, en in fabric['anchors']:
            for p in range(st, en):
                self.anch[node][p] = True
        # blackouts: set of dark phases per link
        self.bl = [set() for _ in fabric['links']]
        for lid, st, en in fabric['blackouts']:
            for p in range(st, en):
                self.bl[lid].add(p)
        # slice membership per phase
        self.sl_of_phase = []
        for p in range(P):
            nominal = O + p * T
            self.sl_of_phase.append(self.slices[(nominal // S) % self.Q])
        self.rho = [(O + p * T) % S for p in range(P)]

    def steps(self, t, i, guard, Hm):
        """Yield (target_t, target_node, wbound, wage) lineage steps."""
        P, N, T, S = self.P, self.n, self.T, self.S
        p = t % P
        yield (t + 1, i, self.v[i][p] * T, 1)
        if not self.slices:
            return
        nominal = self.O + p * T
        sl = self.slices[(nominal // S) % self.Q]
        rho = nominal % S
        for l in sl:
            lk = self.fab['links'][l]
            (n0, s0, g0), (n1, s1, g1) = lk['ends']
            for dirn in (0, 1):
                if dirn == 0:
                    src, gs, dst, gd = n0, g0, n1, g1
                    d, q = lk['delay_ns'][0], lk['defer_rounds'][0]
                else:
                    src, gs, dst, gd = n1, g1, n0, g0
                    d, q = lk['delay_ns'][1], lk['defer_rounds'][1]
                if src != i:
                    continue
                if rho < guard or rho + d + guard > S:
                    continue
                r = d // T
                m = d % T
                L = r + (1 if m else 0)
                bad = False
                for j in range(p, p + L):
                    if j % P in self.bl[l]:
                        bad = True
                        break
                if bad:
                    continue
                Delta = L + q
                # receiver aging
                if m:
                    age = self.v[dst][(p + r) % P] * (T - m)
                    start = p + r + 1
                else:
                    start = p + r
                for j in range(start, start + q):
                    age += self.v[dst][j % P] * T
                yield (t + Delta, dst, Hm[gs][gd] + age, Delta)

    def unrolled(self, guard, Hm, hmax):
        """Lexicographic labels (bound, age) for boundaries 0..hmax."""
        P, N = self.P, self.n
        INF = float('inf')
        lab = {}
        for t in range(hmax + 1):
            for i in range(N):
                if self.anch[i][t % P]:
                    lab[(t, i)] = (0, 0)
            for i in range(N):
                cur = lab.get((t, i))
                if cur is None:
                    continue
                for (tt, j, wb, wa) in self.steps(t, i, guard, Hm):
                    if tt > hmax:
                        continue
                    cand = (cur[0] + wb, cur[1] + wa)
                    old = lab.get((tt, j))
                    if old is None or cand < old:
                        lab[(tt, j)] = cand
        return lab

    def solve(self, upper):
        Hm = hop(profile_=None, upper=upper) if False else None
        return None
